  edMsgGiftHint: ["ההטבה נוספת לכל לקוח שיש לו יום הולדת, גם בלי Wallet, ומופיעה בעמדה כמו כל הטבה.", "تُضاف المكافأة لكل زبون في يوم ميلاده، حتى بدون Wallet، وتظهر في نقطة الخدمة كأي مكافأة.", "Every customer with a birthday gets it, Wallet or not, and staff see it like any other reward."],
  fWelcome: ["נוסח הברכה", "نص الترحيب", "Welcome text"],
  fBirthday: ["נוסח הברכה ליום הולדת", "نص تهنئة عيد الميلاد", "Birthday text"],
  edMsgSpecial: ["הודעה ליום מיוחד", "رسالة ليوم مميز", "Special-day message"],
  edMsgSpecialHint: ["חג, מבצע או חותמת כפולה: מתזמנים הודעה לתאריך ושעה, והיא נשלחת לכל הלקוחות עם הכרטיס ב-Wallet.", "عيد، عرض أو ختم مضاعف: حدّد موعد رسالة وتُرسل لكل الزبائن الذين لديهم البطاقة في Wallet.", "A holiday, a sale or double stamps: schedule a message for a date and time, sent to every customer with the card in Wallet."],
  edMsgSpecialLink: ["לתזמון הודעה", "جدولة رسالة", "Schedule a message"],
  spTitle: ["הודעה ליום מיוחד", "رسالة ليوم مميز", "Special-day message"],
  spIntro: ["ההודעה נשלחת כהתראה לכל הלקוחות ששמרו את הכרטיס ב-Google Wallet, בתאריך ובשעה שתבחר.", "تُرسل الرسالة كإشعار لكل الزبائن الذين حفظوا البطاقة في Google Wallet، في الموعد الذي تختاره.", "Sent as a notification to every customer who saved the card to Google Wallet, at the date and time you pick."],
  spBack: ["ללוח הבקרה", "إلى لوحة التحكم", "Dashboard"],
