  spVars: ["אפשר לכתוב {name} לשם הלקוח ו-{business} לשם העסק.", "يمكنك كتابة {name} لاسم الزبون و-{business} لاسم المحل.", "Use {name} for the customer's name and {business} for the business name."],
  spWhen: ["מתי לשלוח", "موعد الإرسال", "When to send"],
  spReach: ["{n} לקוחות שמרו את הכרטיס ב-Google Wallet ויקבלו את ההודעה.", "{n} زبائن حفظوا البطاقة في Google Wallet وسيصلهم الإشعار.", "{n} customers saved the card to Google Wallet and will get it."],
  spLimit: ["(Google מגביל ל-3 התראות ביום לכל לקוח, כולל התראות החותמות.)", "(تسمح Google بثلاثة إشعارات يومياً لكل زبون، بما فيها إشعارات الأختام.)", "(Google allows 3 notifications a day per customer, stamp notifications included.)"],
  spNotReady: ["Google Wallet עוד לא מחובר במערכת, ולכן כרגע לא תישלח התראה.", "Google Wallet غير متصل بعد، لذلك لن يُرسل إشعار حالياً.", "Google Wallet is not connected yet, so nothing will be sent for now."],
