  forgotHint: ["כתבו את האימייל של החשבון ונשלח קישור לבחירת סיסמה חדשה.", "اكتب بريد الحساب وسنرسل رابطاً لاختيار كلمة مرور جديدة.", "Enter your account email and we'll send a link to choose a new password."],
  forgotSubmit: ["שליחת קישור", "إرسال الرابط", "Send link"],
  forgotSent: ["אם יש חשבון עם האימייל הזה, שלחנו אליו קישור. הוא בתוקף לשעה.", "إذا كان هناك حساب بهذا البريد، فقد أرسلنا إليه رابطاً صالحاً لمدة ساعة.", "If an account uses this email, a link is on its way. It is valid for one hour."],
  err_code_invalid: ["הקוד שגוי או שפג תוקפו.", "الرمز خاطئ أو منتهي الصلاحية.", "The code is wrong or has expired."],
  err_mail_unavailable: ["לא הצלחנו לשלוח אימייל כרגע. נסו שוב בעוד כמה דקות.", "تعذر إرسال البريد الآن. حاول بعد بضع دقائق.", "We couldn't send the email right now. Try again in a few minutes."],
  inviteEmail: ["האימייל של העובד", "بريد الموظف", "Staff member's email"],
  inviteEmailHint: ["רק חשבון עם האימייל הזה יוכל להשתמש בקישור. הקישור בתוקף ל-48 שעות.", "فقط حساب بهذا البريد يمكنه استخدام الرابط. صالح لمدة 48 ساعة.", "Only an account with this email can use the link. It is valid for 48 hours."],
  inviteForEmail: ["ההזמנה מיועדת ל-{email}.", "الدعوة مخصصة لـ {email}.", "This invite is for {email}."],
  err_invite_other_email: ["ההזמנה הזו מיועדת לאימייל אחר. בקשו מבעל העסק הזמנה לאימייל שלכם.", "هذه الدعوة لبريد آخر. اطلب من صاحب المحل دعوة لبريدك.", "This invite is for a different email. Ask the owner for an invite to your email."],
  err_invite_email: ["צריך לכתוב את האימייל של העובד.", "يجب كتابة بريد الموظف.", "Enter the staff member's email."],
  publishedWallet: ["פורסם. {n} כרטיסים שמורים ב-Google Wallet יתעדכנו בדקות הקרובות.", "تم النشر. سيتم تحديث {n} بطاقة محفوظة في Google Wallet خلال الدقائق القادمة.", "Published. {n} cards saved in Google Wallet will update in the next few minutes."],
  eraseCustomer: ["להסיר ולמחוק את הפרטים לצמיתות", "إزالة وحذف التفاصيل نهائياً", "Remove and erase details for good"],
  eraseConfirm: ["למחוק לצמיתות את השם, הטלפון ויום ההולדת של {name}? אי אפשר לשחזר. היסטוריית החותמות נשארת בלי פרטים מזהים.", "حذف الاسم والهاتف وتاريخ الميلاد لـ {name} نهائياً؟ لا يمكن الاسترجاع. يبقى سجل الأختام بدون تفاصيل تعريفية.", "Erase {name}'s name, phone and birthday for good? This cannot be undone. The stamp history stays, without identifying details."],
  accountTitle: ["החשבון שלי", "حسابي", "My account"],
  accountDevices: ["מכשירים", "الأجهزة", "Devices"],
  accountDevicesHint: ["טלפון אבד או נכנסתם ממחשב משותף? אפשר לצאת מכל המכשירים בבת אחת.", "فقدت هاتفك أو دخلت من حاسوب مشترك؟ يمكنك الخروج من كل الأجهزة دفعة واحدة.", "Lost a phone or used a shared computer? Sign out of every device at once."],
  deleteAccount: ["מחיקת החשבון", "حذف الحساب", "Delete account"],
  deleteAccountHint: ["השם והאימייל נמחקים ואי אפשר יהיה להיכנס יותר. בעלי עסק: קודם סוגרים את העסק או מעבירים אותו (כתבו ל-support@perkly.shop).", "يُحذف الاسم والبريد ولن يمكن الدخول بعد ذلك. أصحاب المحلات: أغلقوا المحل أو انقلوه أولاً (اكتبوا إلى support@perkly.shop).", "Your name and email are removed and you can't sign in again. Business owners: close or hand over the business first (write to support@perkly.shop)."],
  deleteAccountConfirm: ["למחוק את החשבון? אי אפשר לבטל.", "حذف الحساب؟ لا يمكن التراجع.", "Delete your account? This cannot be undone."],
  err_account_owns_business: ["החשבון הזה הוא הבעלים של עסק פעיל. כתבו ל-support@perkly.shop כדי לסגור או להעביר אותו קודם.", "هذا الحساب مالك لمحل نشط. اكتب إلى support@perkly.shop لإغلاقه أو نقله أولاً.", "This account owns an active business. Write to support@perkly.shop to close or hand it over first."],
  skipToContent: ["דילוג לתוכן", "انتقال إلى المحتوى", "Skip to content"],
  cardOffline: ["אין חיבור לאינטרנט. זה הכרטיס מהפעם האחרונה שהייתה קליטה, ואפשר להציג אותו לסריקה כרגיל.", "لا يوجد اتصال بالإنترنت. هذه البطاقة من آخر مرة كان فيها اتصال، ويمكن عرضها للمسح كالمعتاد.", "No internet connection. This is the card from the last time you were online; you can still show it to be scanned."],
  edShowName: ["להציג את שם הלקוח על הכרטיס", "إظهار اسم الزبون على البطاقة", "Show the customer's name on the card"],
  edPreview: ["תצוגה מקדימה", "معاينة", "Preview"],
  pvWeb: ["בדפדפן", "في المتصفح", "Browser"],
  pvNoteWeb: ["כך הלקוח רואה את הכרטיס בקישור שלו.", "هكذا يرى الزبون البطاقة عبر رابطه.", "This is how customers see the card from their link."],
  pvNoteApple: ["הדמיה משוערת. ב־Apple Wallet המבנה קבוע: לוגו ושם למעלה, פס תמונה עם החותמות, שורת שדות וקוד. עדיין לא מחובר.", "محاكاة تقريبية. في Apple Wallet الترتيب ثابت: الشعار والاسم، شريط صورة بالأختام، صف حقول ورمز. غير مربوط بعد.", "Approximate preview. Apple Wallet uses a fixed layout: logo and name, an image strip with the stamps, one row of fields and the code. Not connected yet."],
  pvNoteGoogle: ["הדמיה משוערת. ב־Google Wallet מופיעים שם העסק, ההטבה, החותמות וה־QR, ותמונת הרקע כבאנר. הלוגו והצבע בראש הכרטיס הם בינתיים של Perkly.", "محاكاة تقريبية. في Google Wallet يظهر اسم المشروع والمكافأة والأختام ورمز QR، وصورة الخلفية كبانر. الشعار واللون في أعلى البطاقة حالياً لـ Perkly.", "Approximate preview. Google Wallet shows your business name, reward, stamps and QR code, with your background image as the banner. For now the logo and color at the top are Perkly's."],
