  chkTextOk: ["ניגודיות הטקסט {r}:1. קריא היטב.", "تباين النص {r}:1. واضح.", "Text contrast {r}:1. Easy to read."],
  chkTextWarn: ["ניגודיות הטקסט {r}:1. גבולי, מומלץ לפחות 4.5:1.", "تباين النص {r}:1. حدّي، يُنصح بـ 4.5:1.", "Text contrast {r}:1. Borderline; aim for 4.5:1."],
  chkTextBad: ["ניגודיות הטקסט {r}:1. קשה מדי לקריאה.", "تباين النص {r}:1. صعب القراءة جداً.", "Text contrast {r}:1. Too hard to read."],
  chkStampOk: ["החותמות בולטות על הרקע ({r}:1).", "الأختام واضحة على الخلفية ({r}:1).", "Stamps stand out on the background ({r}:1)."],
  chkStampWarn: ["החותמות לא בולטות מספיק ({r}:1). מומלץ לפחות 3:1.", "الأختام غير واضحة كفاية ({r}:1). يُنصح بـ 3:1.", "Stamps don't stand out enough ({r}:1). Aim for 3:1."],
  chkNoLogo: ["אין לוגו. תוצג האות הראשונה של שם הכרטיס.", "لا يوجد شعار. سيظهر الحرف الأول من اسم البطاقة.", "No logo. The first letter of the card name is shown."],
  chkMissingImage: ["תמונה שנבחרה לא נמצאה. העלו אותה שוב.", "صورة مختارة غير موجودة. ارفعها مجدداً.", "A chosen image is missing. Upload it again."],
